    import { orderInfo,refundInfo } from '@/api/kefu'
    export default {
        name: "order_detail",
        props:{
            orderId:{
                type:String | Number,
                default:''
            },
			isReturen:{
				type:Boolean,
				default:false
			}
        },
        data(){
            return {
                orderDetail:{},
                orderList:[],
                columns1: [
                    {
                        title: '商品ID',
                        slot: 'id',
                        maxWidth:80
                    },
                    {
                        title: '商品名称',
                        slot: 'name',
                        minWidth: 160
                    },
                    {
                        title: '商品分类',
                        slot: 'className'
                    },
                    {
                        title: '商品售价',
                        slot: 'price'
                    },
                    {
                        title: '商品数量',
                        slot: 'total_num'
                    }
                ],
				customForm:[]
            }
        },
        mounted() {
            this.getOrderInfo()
        },
        methods:{
            getOrderInfo(){
				(this.isReturen? refundInfo(this.orderId):orderInfo(this.orderId))
				.then(res=>{
				    res.data.orderInfo.add_time =  this.$moment(parseInt(res.data.orderInfo.add_time)*1000).format('YYYY-MM-DD')
				    this.orderDetail = res.data;
				    this.orderList = res.data.orderInfo.cartInfo;
				    let customForm = [];
				    res.data.orderInfo.custom_form.forEach(item=>{
				      if((item.value && ['uploadPicture','dateranges'].indexOf(item.name) == -1) || (item.value.length && ['uploadPicture','dateranges'].indexOf(item.name) != -1)){
				        customForm.push(item);
				      }
				    })
				    let count = Math.ceil(customForm.length / 2);
				    let customArray = new Array();
				    for (let i = 0; i < count; i++) {
				      let list = customForm.slice(i * 2, i * 2 + 2);
				      if (list.length)
				        customArray.push({
				          list: list
				        });
				    }
				    this.customForm = customArray;
				})
			}
        }
    }
